-- 用户管理权限 INSERT INTO permissions (code, name, module, resource, action, description, created_at) VALUES ('USER:MANAGE', '用户管理', 'USER', 'MANAGE', 'ALL', '完整的用户管理权限，包括创建、编辑、删除用户', NOW()), ('USER:CREATE', '创建用户', 'USER', 'USER', 'CREATE', '可以创建新用户', NOW()), ('USER:EDIT', '编辑用户', 'USER', 'USER', 'EDIT', '可以编辑用户信息', NOW()), ('USER:DELETE', '删除用户', 'USER', 'USER', 'DELETE', '可以删除用户', NOW());
-- 角色管理权限 INSERT INTO permissions (code, name, module, resource, action, description, created_at) VALUES ('ROLE:MANAGE', '角色管理', 'ROLE', 'MANAGE', 'ALL', '完整的角色管理权限，包括创建、编辑、删除角色', NOW()), ('ROLE:CREATE', '创建角色', 'ROLE', 'ROLE', 'CREATE', '可以创建新角色', NOW()), ('ROLE:EDIT', '编辑角色', 'ROLE', 'ROLE', 'EDIT', '可以编辑角色信息', NOW()), ('ROLE:DELETE', '删除角色', 'ROLE', 'ROLE', 'DELETE', '可以删除角色', NOW());
-- 权限管理权限 INSERT INTO permissions (code, name, module, resource, action, description, created_at) VALUES ('PERMISSION:MANAGE', '权限管理', 'PERMISSION', 'MANAGE', 'ALL', '完整的权限管理权限，包括创建、编辑、删除权限', NOW()), ('PERMISSION:CREATE', '创建权限', 'PERMISSION', 'PERMISSION', 'CREATE', '可以创建新权限', NOW()), ('PERMISSION:EDIT', '编辑权限', 'PERMISSION', 'PERMISSION', 'EDIT', '可以编辑权限信息', NOW()), ('PERMISSION:DELETE', '删除权限', 'PERMISSION', 'PERMISSION', 'DELETE', '可以删除权限', NOW());
